import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Acceptance and evidence","description":"How Hearth decides a capability is really complete and which evidence must be kept.","frontmatter":{"title":"Acceptance and evidence","description":"How Hearth decides a capability is really complete and which evidence must be kept.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/acceptance.md","filePath":"en/delivery/acceptance.md","lastUpdated":null}'),i={name:"en/delivery/acceptance.md"};function r(c,e,d,o,l,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="acceptance-and-evidence" tabindex="-1">Acceptance and evidence <a class="header-anchor" href="#acceptance-and-evidence" aria-label="Permalink to &quot;Acceptance and evidence&quot;">​</a></h1><p class="lead">Hearth does not treat &quot;the page exists&quot;, &quot;the code merged&quot;, or &quot;the tests pass&quot; as delivery. Acceptance answers three questions: what was done, where the evidence is, and what is still unproven.</p><h2 id="definition-of-done" tabindex="-1">Definition of done <a class="header-anchor" href="#definition-of-done" aria-label="Permalink to &quot;Definition of done&quot;">​</a></h2><p>A capability is complete only when all of the following hold:</p><ol><li><strong>A user-visible result exists.</strong> The result appears in the UI, an artifact, or a receipt, not only in the model saying &quot;done&quot;.</li><li><strong>Evidence can be checked.</strong> Inputs, run records, artifact digests, approvals, and external receipts are traceable.</li><li><strong>A failure path exists.</strong> Failure becomes recoverable or explicitly failed; success is not fabricated and external actions are not blindly retried.</li><li><strong>Real acceptance happened.</strong> The agreed scenario ran with a real task, device, or account; automated tests cannot replace it.</li></ol><h2 id="test-levels" tabindex="-1">Test levels <a class="header-anchor" href="#test-levels" aria-label="Permalink to &quot;Test levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Proves</th><th>Does not prove</th></tr></thead><tbody><tr><td>Unit tests</td><td>Pure logic such as state machines, budgets, permissions, extraction, and encryption</td><td>Real environment, accounts, or user willingness</td></tr><tr><td>API / integration tests</td><td>Server routes, projections, approvals, backup, sync, and other code loops</td><td>Real desktop, real network, or long-running operation</td></tr><tr><td>Isolated-instance runs</td><td>The end-to-end path works in a controlled environment</td><td>Real user tasks and willingness to recover</td></tr><tr><td>Real task acceptance</td><td>Agreed tasks complete in a real environment and can be checked</td><td>Long-term stability and every boundary</td></tr><tr><td>Long-running acceptance</td><td>Multi-week operation, resource drift, and upgrade rollback</td><td>Uncovered task types</td></tr></tbody></table><p>The current automated baseline is <strong>40 test files and 199 tests</strong>. It covers the service layer, API, model protocols, native tool loop, budgets, permissions, checkpoints, proposal confirmation, desktop boundaries, memory, methods, sync, security, backup, and operations. It does not replace real acceptance.</p><h2 id="reproduce-the-current-checks" tabindex="-1">Reproduce the current checks <a class="header-anchor" href="#reproduce-the-current-checks" aria-label="Permalink to &quot;Reproduce the current checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p>Run on 2026-11-06:</p><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td><code>npm test</code></td><td>40 files, 199 tests passed</td></tr><tr><td><code>npm run typecheck</code></td><td>Passed</td></tr><tr><td><code>npm run build</code></td><td>Passed</td></tr><tr><td><code>npm run docs:build</code></td><td>Passed</td></tr></tbody></table><h2 id="evidence-rules" tabindex="-1">Evidence rules <a class="header-anchor" href="#evidence-rules" aria-label="Permalink to &quot;Evidence rules&quot;">​</a></h2><h3 id="keep-failure-evidence" tabindex="-1">Keep failure evidence <a class="header-anchor" href="#keep-failure-evidence" aria-label="Permalink to &quot;Keep failure evidence&quot;">​</a></h3><ul><li>Preserve HTTP status, final URL, fetch time, and failure cause when a page fails.</li><li>A task missing artifacts becomes recoverable or failed; empty files are not results.</li><li>Reconcile uncertain external actions before retrying.</li><li>Prove that a revoked device cannot operate with a drill, not with a sentence in a document.</li></ul><h3 id="external-actions-must-be-checkable" tabindex="-1">External actions must be checkable <a class="header-anchor" href="#external-actions-must-be-checkable" aria-label="Permalink to &quot;External actions must be checkable&quot;">​</a></h3><ul><li>Produce a preview before the action.</li><li>Bind approval to a parameter fingerprint and execute once.</li><li>Record the result and receipt in the effect ledger.</li><li>When approval is rejected or expires, update the draft and task state.</li></ul><h3 id="no-fabricated-success" tabindex="-1">No fabricated success <a class="header-anchor" href="#no-fabricated-success" aria-label="Permalink to &quot;No fabricated success&quot;">​</a></h3><ul><li>T04&#39;s WCAG access failure is preserved as evidence.</li><li>T07 failed because a test file was uncommitted; nothing was pushed and no PR was created.</li><li>T08&#39;s comment approval is still <code>pending</code>; there is no external effect.</li><li>When a backup excludes artifact bodies, both the UI and the docs say so.</li></ul><h2 id="acceptance-record-template" tabindex="-1">Acceptance record template <a class="header-anchor" href="#acceptance-record-template" aria-label="Permalink to &quot;Acceptance record template&quot;">​</a></h2><p>Keep at least the following for each completed phase or workstream:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Workstream:</span></span>
<span class="line"><span>Acceptance date:</span></span>
<span class="line"><span>Real environment:</span></span>
<span class="line"><span>Task count:</span></span>
<span class="line"><span>Passed / failed / pending approval:</span></span>
<span class="line"><span>Input and output paths per task:</span></span>
<span class="line"><span>Failure causes and recovery:</span></span>
<span class="line"><span>External actions and receipts:</span></span>
<span class="line"><span>Still unproven boundaries:</span></span></code></pre></div><h2 id="phase-one-evidence-index" tabindex="-1">Phase-one evidence index <a class="header-anchor" href="#phase-one-evidence-index" aria-label="Permalink to &quot;Phase-one evidence index&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Evidence</th><th>Location</th></tr></thead><tbody><tr><td>Phase-one acceptance report</td><td><code>eval/phase-1-acceptance.md</code></td></tr><tr><td>Runs and artifacts for 15 tasks</td><td><code>eval/runs/T01</code> … <code>eval/runs/T15</code></td></tr><tr><td>Run manifests and SHA-256</td><td><code>run-manifest.json</code> in each task directory</td></tr><tr><td>Automated tests</td><td><code>npm test</code></td></tr><tr><td>Typecheck and build</td><td><code>npm run typecheck</code>, <code>npm run build</code></td></tr></tbody></table><p>Per-task results are in <a href="/hearth-os/en/delivery/mvp.html">Phase-one MVP acceptance</a>.</p><h2 id="next-acceptance-focus" tabindex="-1">Next acceptance focus <a class="header-anchor" href="#next-acceptance-focus" aria-label="Permalink to &quot;Next acceptance focus&quot;">​</a></h2><p>The next round does not add pages that only look complete. It closes:</p><ol><li>Real email/calendar accounts and 10–15 everyday content tasks.</li><li>At least 5 real desktop tasks and high-risk failure drills.</li><li>Mobile approval/takeover and 5–10 proactive interruption tests.</li><li>Wrong-memory/wrong-method drills and before/after production comparison.</li><li>Two-device, offline, lost-device, and backup-restore drills.</li><li>Multi-week operation, resource drift, and upgrade rollback.</li></ol><p>Until these finish, phases two through six remain &quot;partial&quot;.</p>`,29)])])}const k=t(i,[["render",r]]);export{u as __pageData,k as default};
